FAR struct i2c_master_s *d13x_i2c_initialize(int bus)
{
  FAR struct d13x_i2c_dev_s *priv;
  uint32_t reg;

  switch (bus)
    {
      case 0:
        priv = &g_d13x_i2c0;
        break;
      case 1:
        priv = &g_d13x_i2c1;
        break;
      case 2:
        priv = &g_d13x_i2c2;
        break;
      default:
        ierr("Invalid I2C bus: %d\n", bus);
        return NULL;
    }

  /* 确保模块禁用 */

  i2c_module_disable(priv->base);

  /* 设置 master 模式 */

  reg = i2c_getreg(priv->base, I2C_CTL);
  reg |= I2C_CTL_MASTER | I2C_CTL_RESTART_EN;
  i2c_putreg(priv->base, I2C_CTL, reg);

  /* 设置 SCL 时序 (APB0 = 100MHz) */

  d13x_i2c_set_speed(priv->base, D13X_APB0_FREQ);

  iinfo("I2C%d initialized at 0x%08" PRIx32 "\n", bus, priv->base);

  return &priv->dev;
}

