static int gt911_set_power(const struct gt9xx_board_s *state, bool on)
{
  if (on)
    {
      /* RST output LOW */

      gpio_set_direction(GT911_RST_PIN, 1);
      gpio_set_value(GT911_RST_PIN, 0);
      up_mdelay(10);

      /* INT output LOW — selects I2C address 0x5D */

      gpio_set_direction(GT911_INT_PIN, 1);
      gpio_set_value(GT911_INT_PIN, 0);
      up_mdelay(2);

      /* RST output HIGH */

      gpio_set_value(GT911_RST_PIN, 1);
      up_mdelay(5);

      /* RST set to input (floating) */

      gpio_set_direction(GT911_RST_PIN, 0);

      /* INT stays LOW, wait for GT911 to latch address */

      up_mdelay(50);

      /* INT set to input (floating) */

      gpio_set_direction(GT911_INT_PIN, 0);
    }
  else
    {
      gpio_set_direction(GT911_RST_PIN, 1);
      gpio_set_value(GT911_RST_PIN, 0);
    }

  return OK;
}

