/****************************************************************************
 * Private Functions - 显示管线初始化
 ****************************************************************************/

static int d13x_pll_disp_init(void)
{
  uint32_t reg;
  uint32_t timeout;

  /* 配置 PLL_FRA2 → 364MHz (24MHz × (N+1 + F/16384)) */

  reg = getreg32(CMU_PLL_FRA2_GEN);
  reg &= ~(PLL_FRA2_N_MASK | PLL_FRA2_F_MASK);
  reg |= (PLL_FRA2_N_VALUE << PLL_FRA2_N_SHIFT);
  reg |= (PLL_FRA2_F_VALUE << PLL_FRA2_F_SHIFT);
  reg |= PLL_FRA2_EN;
  putreg32(reg, CMU_PLL_FRA2_GEN);

  /* 等待 PLL 锁定 */

  timeout = PLL_FRA2_TIMEOUT;
  while (!(getreg32(CMU_PLL_FRA2_INT) & PLL_FRA2_INT_LOCK))
    {
      if (--timeout == 0)
        {
          ierr("PLL_FRA2 lock timeout\n");
          return -ETIMEDOUT;
        }
    }

  return OK;
}

static void d13x_de_clk_enable(void)
{
  uint32_t reg;

  /* 使能 DE 显示时钟 */

  reg = getreg32(CMU_CLK_DISP);
  reg |= CLK_DISP_SCLK_GATE | CLK_DISP_PIX_GATE;
  putreg32(reg, CMU_CLK_DISP);
}

static void d13x_lvds_clk_enable(void)
{
  uint32_t reg;

  /* 使能 LVDS 时钟门控 */

  reg = getreg32(CMU_CLK_LVDS);
  reg |= CLK_LVDS_GATE;
  putreg32(reg, CMU_CLK_LVDS);
}

static void d13x_de_timing_enable(void)
{
  /* 水平时序 */

  putreg32((PANEL_HBP << 24) | (PANEL_HFP << 12) | PANEL_HSYNC,
           D13X_DE_BASE + DE_TIMING_H_PORCH);

  /* 垂直时序 */

  putreg32((PANEL_VBP << 24) | (PANEL_VFP << 12) | PANEL_VSYNC,
           D13X_DE_BASE + DE_TIMING_V_PORCH);

  /* 同步脉冲宽度 */

  putreg32((PANEL_HSYNC << 16) | PANEL_VSYNC,
           D13X_DE_BASE + DE_TIMING_SYNC_PLUSE);

  /* 活动区域尺寸 */

  putreg32((PANEL_HACTIVE << 16) | PANEL_VACTIVE,
           D13X_DE_BASE + DE_TIMING_ACTIVE_SIZE);

  /* 使能 DE 时序输出 */

  putreg32(DE_TIMING_EN, D13X_DE_BASE + DE_TIMING_CTRL_EN);
}

static void d13x_lvds_phy_enable(void)
{
  lvds_putreg(LVDS_0_SWAP, AIC_LVDS_LINES);
  lvds_putreg(LVDS_1_SWAP, AIC_LVDS_LINES);
  lvds_putreg(LVDS_0_POL_CTL, AIC_LVDS_POL);
  lvds_putreg(LVDS_1_POL_CTL, AIC_LVDS_POL);
  lvds_putreg(LVDS_0_PHY_CTL, AIC_LVDS_PHY);
  lvds_putreg(LVDS_1_PHY_CTL, AIC_LVDS_PHY);

  uint32_t ctl = 0;
  ctl |= LVDS_CTL_MODE(LVDS_NS);
  ctl |= LVDS_CTL_LINK(LVDS_SINGLE_LINK0);
  if (AIC_LVDS_LINK_SWAP_EN)
    {
      ctl |= LVDS_CTL_SWAP_EN;
    }

  if (AIC_LVDS_SYNC_MODE_EN)
    {
      ctl |= LVDS_CTL_SYNC_MODE_EN;
    }

  lvds_putreg(LVDS_CTL, ctl);
  lvds_putreg(LVDS_CTL, ctl | LVDS_CTL_EN);
}

