static int d13x_pll_disp_init(void)
{
  uint32_t reg;
  uint32_t timeout;

  /* 配置 PLL_FRA2 → 364MHz (24MHz × (N+1 + F/16384)) */

  reg = getreg32(CMU_PLL_FRA2_GEN);
  reg &= ~PLL_FRA2_N_MASK;
  reg |= (PLL_FRA2_N_VALUE << PLL_FRA2_N_SHIFT);
  reg |= PLL_FRA2_EN | PLL_FRA2_OUT_SYS;
  putreg32(reg, CMU_PLL_FRA2_GEN);

  /* 配置小数分频 */

  reg = getreg32(CMU_PLL_FRA2_FRA);
  reg &= ~(PLL_FRA2_FRAC_EN | PLL_FRA2_F_MASK);
  reg |= (PLL_FRA2_F_VALUE << PLL_FRA2_F_SHIFT);

/* 分配帧缓冲内存（PSRAM 区域，cacheable） */

dev->fbmem = kumm_memalign(64, dev->fblen);
if (dev->fbmem == NULL)
  {
    ierr("Failed to allocate framebuffer (%zu bytes)\n", dev->fblen);
    return -ENOMEM;
  }

memset(dev->fbmem, 0, dev->fblen);

/* 显示管线初始化: PLL → DE时钟 → LVDS时钟 → DE时序 → LVDS PHY */

int ret = d13x_pll_disp_init();
if (ret < 0)
  {
    ierr("PLL lock timeout\n");
    return ret;
  }

